WITH scored AS (SELECT id, last_restock, MIN(quantity) OVER w_part AS last7_min_quantity, SUM(quantity) OVER w_part AS last7_sum_quantity, AVG(quantity) OVER w_part AS last7_avg_quantity FROM inventory WINDOW w_part AS (PARTITION BY product_id, store_id ORDER BY quantity ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT id, last7_min_quantity FROM scored ORDER BY last7_min_quantity DESC;
